// Üretilen dosya: tool/ozgun/uret.py. Sinema ve TV · Kurgu kuramları, ses tasarımı, foley, dublaj ve post-prodüksiyon (Kuleşov etkisi, paralel kurgu, sıçramalı kesme, diegetik ses, foley ve ADR) (kolay).
const ozCinema16Kolay = <(String, String, List<String>, String)>[
  ('Georges Méliès\'nin Paris\'teki Opera Meydanı\'nda çekim yaparken kamerasının takılması sonucu bir otobüsün cenaze arabasına dönüştüğünü fark etmesiyle sinemaya kazandırdığı erken dönem kurgu hilesi hangisidir?', 'Durdurma hilesi (stop trick)', ['Çift pozlama (double exposure)', 'Paralel kurgu (cross-cutting)', 'Geriye sarma (reverse motion)'], 'Méliès kameranın tutukluk yapmasıyla keşfettiği durdurma hilesi sayesinde nesneleri aniden yok etme veya dönüştürme tekniğini geliştirmiştir.'),
  ('1903 yapımı \'Büyük Tren Soygunu\' filminde telgrafçının bağlandığı sahne ile haydutların kaçış sahnesi arasında kesme yapılması izleyiciye hangi anlatısal algıyı kazandırmıştır?', 'Farklı mekânlardaki olayların eşzamanlılığı', ['Karakterin geçmişteki travmatik anıları', 'Diyalogların dudak hareketleriyle uyumu', 'Tek çekimde kesintisiz gerçeklik hissi'], 'Edwin S. Porter farklı yerlerde geçen eylemler arasında kesme yaparak eşzamanlılık duygusunun kurguyla kurulabileceğini göstermiştir.'),
  ('D. W. Griffith\'in \'son dakikada kurtuluş\' sekanslarında tehlikedeki kurbanlar ile yardıma koşan kurtarıcılar arasında gidip gelen çekimleri hızlandırarak gerilimi tırmandırdığı teknik nedir?', 'Almaşık (paralel) kurgu', ['Entelektüel montaj', 'Sıçramalı kesme', 'Grafiksel eşleşme'], 'Griffith iki ayrı mekânda eşzamanlı gelişen eylemleri almaşık biçimde kurgulayıp plan sürelerini kısaltarak dramatik gerilim üretmiştir.'),
  ('Çarlık dönemi Rus aktörü İvan Mozjuhin\'in ifadesiz yakın plan yüz görüntüsünü bir tabak çorba, tabuttaki çocuk ve divanda uzanan kadın planlarıyla ardışık kurgulayarak izleyicide açlık, hüzün ve arzu algısı yaratan kuramcı kimdir?', 'Lev Kuleşov', ['Dziga Vertov', 'Aleksandr Dovjenko', 'Grigori Kozintsev'], 'Lev Kuleşov bu ünlü deneyiyle sinemasal anlamın tekil çekimin içeriğinden ziyade planların yan yana gelişinden doğduğunu kanıtlamıştır.'),
  ('Pudovkin\'in kurgu sınıflandırmasında açlıktan kıvranan yoksul bir adamın görüntüsünden hemen sonra zengin bir ziyafet sofrasına kesme yapılması hangi ilkeye dayanır?', 'Karşıtlık (kontrast) ilkesi', ['Eşzamanlılık ilkesi', 'Leitmotiv (tekrarlanan motif) ilkesi', 'Grafik devamlılık ilkesi'], 'Pudovkin\'in beş ilişkisel kurgu türünden biri olan karşıtlık ilkesi, zıt durumları art arda getirerek izleyicideki duygusal etkiyi keskinleştirir.'),
  ('Potemkin Zırhlısı\'nın sonunda zırhlının toplarını ateşlemesinin hemen ardından uyuyan, uyanan ve kükreyen üç ayrı taş aslan heykelinin art arda kurgulanması neyi simgeler?', 'Halkın uyanışını ve devrimci öfkenin ayağa kalkışını', ['Odessa limanındaki mimari eserlerin savaşta yıkılışını', 'Çarlık ordusunun denizden gelen saldırıyı püskürttüğünü', 'Denizcilerin gemiyi terk edip saraya sığındığını'], 'Ayzenştayn cansız üç farklı mermer aslan heykelini kurguyla hareketlendirerek Rus halkının uykudan uyanıp başkaldırması metaforunu yaratmıştır.'),
  ('Senaryo, profesyonel oyuncu, dekor ve kostüm gibi burjuva tiyatrosu kalıntılarını reddederek insan gözünden daha kusursuz olan mekanik mercekle \'hayatı hazırlıksız yakalamayı\' savunan Dziga Vertov kavramı hangisidir?', 'Kino-Glaz (Sinema-Göz)', ['Kino-Kulak (Yumruk-Sinema)', 'Yaratıcı Coğrafya', 'Derin Odaklı Mizansen'], 'Dziga Vertov \'Sinema-Göz\' manifestosuyla kurmaca dramayı reddetmiş, kameranın ve kurgunun çıplak yaşam gerçekliğini çözümlemesini savunmuştur.'),
  ('Lumière Kardeşler\'in 1895 tarihli \'İşçilerin Fabrikadan Çıkışı\' ve \'Trenin Gara Girişi\' gibi ilk filmlerinde kurgunun durumu aşağıdakilerden hangisiyle tanımlanır?', 'Sabit kamerayla tek planda çekilen ve kurgusal kesme içermeyen yapı', ['Yakın plan yüz ifadeleriyle genel planları almaşık birleştiren yapı', 'Geriye dönüşlerle tren yolculuğunun başlangıcını özetleyen yapı', 'Hareket eşleşmesiyle istasyonun içinden vagonun içine geçen yapı'], 'Lumière filmleri tek bir film makarasının sabit çerçeveden kesintisiz pozlandığı \'tek planlık\' (single-shot) erken dönem örnekleridir.'),
  ('Fiziksel olarak montaj masasında selüloit film şeritlerinin makas veya giyotinle kesilip aseton bazlı yapıştırıcı ya da bantla fiziksel olarak uç uca eklenmesi işlemine geleneksel post-prodüksiyonda ne ad verilir?', 'Splicing (ekleme / yapıştırma)', ['Rendering (sayısal dışa aktarma)', 'Color grading (renk derecelendirme)', 'Booming (üstten ses toplama)'], 'Analog kurgu döneminde film şeritlerinin kesilip ek yerlerinden fiziksel olarak birleştirilmesi işlemine splice/splicing denir.'),
  ('D. W. Griffith\'in kameramanı Billy Bitzer ile birlikte geliştirdiği ve kurguda dramatik bir detayı vurgulamak için ekranın kenarlarını karartıp yalnızca dairesel bir alanı açık bırakma tekniği nedir?', 'İrisleme', ['Anamorfik sıkıştırma', 'Sıçramalı kesme', 'Çoklu ses bindirmesi'], 'Sessiz sinema döneminde yakın plan etkisi yaratmak veya sahneyi açıp kapatmak için objektif önündeki diyafram benzeri maskeyle yapılan dairesel daraltmaya irisleme denir.'),
  ('Sessiz sinema kurgusunda iki görüntü planının arasına yerleştirilen, karakterlerin repliklerini aktaran veya zaman-mekân geçişini açıklayan yazılı kartlara ne ad verilir?', 'Ara yazı (intertitle)', ['Altyazı (subtitle)', 'Zaman kodu (timecode)', 'Klaket fişi (slate sheet)'], 'Ara yazılar görüntünün üzerine bindirilmez; kurguda ayrı bir siyah kart çekimi olarak iki planın arasına eklenir.'),
  ('Sessiz bir filmde karakterin dudakları hareket etmeye başladıktan hemen sonra konuşma metnini içeren ara yazıya kesilmesi ve cümlenin bitiminde tekrar oyuncunun yüzüne dönülmesi hangi ara yazı türüdür?', 'Diyalog ara yazısı', ['Açıklayıcı anlatıcı ara yazısı', 'Bölüm başlığı jeneriği', 'Bant reklam yazısı'], 'Sessiz sinemada ara yazılar işlevlerine göre öyküyü özetleyen \'açıklayıcı\' (expository) ve karakter konuşmasını veren \'diyalog\' ara yazıları olarak ikiye ayrılır.'),
  ('Fransızca kökenli \'montage\' sözcüğü Sovyet kuramında tüm yaratıcı birleştirme sürecini karşılarken, klasik Amerikan stüdyo terminolojisinde daha dar anlamıyla neyi ifade eder?', 'Uzun bir zaman dilimini veya süreci müzik eşliğinde kısa çekimlerle özetleyen sekansı', ['Filmin tüm diyalog sahnelerinde uygulanan açı-karşı açı diyalog kurgusunu', 'Çekim bittikten sonra bozuk ses kayıtlarının stüdyoda yeniden seslendirilmesini', 'Negatif filmin banyo kazanlarında kimyasal ilaçlarla yıkanma aşamasını'], 'Fransızca ve Rusçada \'montaj\' genel olarak kurgu demektir; İngilizce/Hollywood kullanımında ise \'montage\' (montaj sekansı) zamanı sıkıştıran özetleyici sekansları anlatır.'),
  ('Sovyet montaj okulunun kuramsal yükselişinde 1920\'lerdeki hangi maddi ve toplumsal koşul belirleyici bir rol oynamıştır?', 'Okuma yazma oranının düşük olduğu geniş halk kitlelerine devrimci fikirleri görsel yolla hızla aktarma ihtiyacı', ['Özel stüdyolar arasındaki gişe rekabetinde pahalı yıldız oyuncuları öne çıkarma arzusu', 'Üç boyutlu sinema salonlarının inşası için yabancı sermaye çekme zorunluluğu', 'Televizyon yayınlarının başlamasıyla sinema seyircisinin evlere kapanması'], 'Çok dilli ve okuryazarlığın düşük olduğu Sovyet coğrafyasında sinema ve çarpıcı görsel montaj, Lenin\'in \'bizim için tüm sanatların en önemlisi\' sözü doğrultusunda en etkili eğitim ve ajitasyon aracı görülmüştür.'),
  ('Dziga Vertov\'un \'Kameralı Adam\' filminde Moskova tramvaylarının altında yatan kameraman görüntüsü ile hızla yaklaşan tramvay tekerleklerinin almaşık kurgulanması izleyiciye neyi hatırlatır?', 'Görüntüyü yakalayan sinema emekçisinin tehlikeli ve fiziksel çalışma sürecini', ['Kurmaca bir intihar öyküsünün son dakikada polis tarafından engellenişini', 'Tramvay sürücülerinin trafik kurallarına uymadığını gösteren kamu spotunu', 'Kameranın uzaktan kumandayla insansız biçimde çalıştırıldığını'], 'Vertov kameraman Mihail Kaufman\'ı çalışırken görüntüleyip kurgulayarak sinemacılığı endüstriyel üretim ve emek süreçlerinin ayrılmaz bir parçası olarak sunar.'),
  ('Kurgu tarihinde \'kesme\' (cut) işleminin yalnızca fiziksel bir makara birleştirme olmaktan çıkıp psikolojik ve dramatik bir anlatım aracına dönüşmesi hangi iki alanın ayrışmasını sağlamıştır?', 'Tiyatro sahnesinin sabit izleme mesafesi ile sinemanın değişken bakış açılı anlatım dilinin', ['Fotoğrafçılıktaki gümüş nitrat banyosu ile sinemadaki selüloit taban kimyasının', 'Radyo tiyatrosundaki ses efektleri ile opera sahnesindeki canlı orkestra düzeninin', 'Roman yazarlığındaki bölüm adlandırmaları ile gazete tefrikalarının sayfa tasarımının'], 'Kurgu sayesinde kamera sabit koltuktaki tiyatro seyircisi olmaktan kurtulmuş, sahnenin içine girip ölçek ve açı değiştirerek sinemayı bağımsız bir sanat yapmıştır.'),
  ('Vsevolod Pudovkin\'in kurgu üzerine yazdığı ve 1920\'lerin sonunda Batı dillerine çevrilerek sinema okullarında uzun yıllar temel kaynak olarak okutulan kitabının ana tezi nedir?', 'Sinema sanatının temelinin oyunculuk veya sahnelemeden önce kurgu (montaj) olduğu', ['Kurgucunun yönetmenin çektiği plan sırasını değiştirmesinin sanatsal açıdan etik dışı olduğu', 'Sesli filmlerin icadıyla birlikte yakın plan çekimlere artık gerek kalmadığı', 'Renkli filmlerde hızlı kesmelerin izleyici gözünü yorduğu için yasaklanması gerektiği'], 'Pudovkin \'Sinemanın temeli montajdır\' şiarıyla, tek başına ham çekimin yalnızca malzeme olduğunu, sanatsal formun kurgu masasında doğduğunu savunmuştur.'),
  ('Mihail Romm ve sonradan Andrey Tarkovski gibi ustaları yetiştiren, kurgu kuramının akademik disiplin olarak okutulduğu Moskova\'daki dünyanın en eski film okulunun kısaltması nedir?', 'VGİK', ['FEMIS', 'FAMU', 'AFI'], '1919\'da Vladimir Gardin ve Lev Kuleşov gibi öncülerle kurulan Tüm Birlik Devlet Sinematografi Enstitüsü (VGİK) Sovyet kurgu okulunun akademik merkezidir.'),
  ('Klasik Hollywood anlatısında izleyicinin kesme noktalarını bilinçli olarak fark etmemesini ve tüm dikkatini öyküye vermesini amaçlayan kurgu sistemine ne ad verilir?', 'Görünmez (devamlılık) kurgusu', ['Diyalektik çarpışma ve yabancılaştırma kurgusu', 'Özdüşünümsel ve parçalı avangart kurgu sistemi', 'Rastlantısal sıçramalara dayalı deneysel montaj'], 'Devamlılık kurgusu (continuity editing), uzam ve zaman geçişlerini pürüzsüzleştirerek kurgu işlemini izleyici gözünden gizlemeyi hedefler.'),
  ('Bir karakterin kapıyı açmak üzere koluna uzandığı orta çekimden, kapının açılıp karakterin içeri adım attığı karşı açı çekime tam hareketin ortasında geçilmesi hangi tekniğe örnektir?', 'Harekette kesme', ['Zaman sıkıştıran eliptik sıçrama kesmesi', 'Öykü dışı görsel metafor yerleştirme', 'Kararmayla başlayıp açılmayla biten geçiş'], 'Harekette kesme (match on action), fiziksel eylemin enerjisini iki çekim arasında bölerek gözün kesme yerini fark etmesini engeller.'),
  ('Kadrajın solunda durup ekranın sağ dışına doğru dikkatle bakan bir dedektifin çekiminden hemen sonra masanın üzerindeki kanlı bıçağın yakın planına kesilmesi hangi ilkeyle çalışır?', 'Bakış yönü eşleşmesi', ['Otuz derece kamera uzaklaştırma kuralı', 'Eşzamanlı paralel takip kurgusu ilkesi', 'Ses kuşağını görüntüden önce başlatma'], 'Bakış yönü eşleşmesi, ilk çekimde karakterin kadraj dışına yönelen bakışını ikinci çekimde baktığı nesneyle birleştirerek mekânsal mantık kurar.'),
  ('Karşılıklı yemek yiyen iki oyuncunun arasına çizildiği varsayılan hayali doğrunun hep aynı tarafında kalarak çekim yapmayı zorunlu kılan devamlılık ilkesi hangisidir?', '180 derece (aks / eksen) kuralı', ['Altın oran çerçeve bölünmesi kuralı', 'Derin odaklı hiperfokal mesafe kuralı', 'Üç noktalı stüdyo aydınlatma kuralı'], '180 derece kuralı korunduğunda ekranda soldaki karakter hep solda, sağdaki karakter hep sağda kalır ve bakış yönleri tutarlı biçimde karşılaşır.'),
  ('Stanley Kubrick\'in \'2001: Bir Uzay Destanı\' filminde tarih öncesi insansı maymunun havaya fırlattığı kemiğin dönerken yörüngedeki uzay aracına dönüşmesi hangi geçiş türünün simgeleşmiş örneğidir?', 'Grafik eşleşmeli kesme', ['Sesten görüntüye gecikmeli L-kesme', 'Merkezden dışa doğru dairesel silinme', 'Karşı açıdan omuz üstü diyalog kesmesi'], 'Kemik ile uzay gemisinin biçimsel ve hareketsel benzerliği üzerinden yapılan bu grafik eşleşme, milyonlarca yıllık insanlık evrimini tek kesmede birleştirir.'),
  ('Yeni başlayan bir sahnenin ilk saniyelerinde binanın dışını, sokağı veya odanın genel yerleşimini göstererek izleyiciye \'neredeyiz ve kimler nerede duruyor\' bilgisini veren çekim hangisidir?', 'Kurucu çekim (establishing shot)', ['Aşırı yakın detay çekimi (extreme close-up)', 'Öznel bakış açısı çekimi (point of view)', 'Ters açı tepki çekimi (reaction shot)'], 'Kurucu çekim sahnenin coğrafi ve mekânsal koordinatlarını kurar; ardından gelen yakın diyalog kesmelerinde izleyici karakterlerin konumunu şaşırmaz.'),
  ('Birinci görüntünün yavaşça şeffaflaşarak kaybolurken ikinci görüntünün aynı anda yavaşça belirmesiyle oluşan ve genellikle zaman geçişini yumuşakça hissettiren optik geçiş nedir?', 'Zincirleme geçiş (dissolve / lap dissolve)', ['Sert kesme (hard / straight cut)', 'Kırbaç kaydırma (whip pan)', 'Eksen içi sıçrama (axial jump)'], 'Zincirleme (dissolve), iki çekimin kısa bir süre üst üste binmesiyle gerçekleşir ve kesmeye kıyasla daha yumuşak bir zaman veya ruh hali geçişi ifade eder.'),
  ('Bir perdenin ya da bölümün tamamen kapandığını, aradan uzun bir zaman geçtiğini hissettirmek için görüntünün yavaşça tam siyaha gömülmesi işlemine ne ad verilir?', 'Kararma (fade-out)', ['Açılma (fade-in)', 'Silinme (wipe)', 'Bindirme (superimposition)'], 'Görüntünün siyaha düşmesi (fade-out), noktalama işaretlerindeki paragraf veya bölüm sonu gibi güçlü bir anlatısal duraklama işlevi görür.'),
  ('Akira Kurosava\'nın \'Yedi Samuray\' ve \'Gizli Kale\' filmleri ile bundan esinlenen George Lucas\'ın \'Yıldız Savaşları\' serisinde yeni görüntü bir çizgi boyunca önceki görüntüyü iterek ekranı kapladığında hangi geçiş kullanılmış olur?', 'Silinme (wipe)', ['Kararma-açılma (fade to black)', 'Harekette kesme (cutting on action)', 'Ses köprülü L-kesme (split edit)'], 'Silinme (wipe) geçişinde B çekimi yatay, dikey, çapraz veya yıldız biçimli bir sınır çizgisiyle A çekiminin üstünü süpürerek görünür hale gelir.'),
  ('İki kişinin karşılıklı konuştuğu bir sahnede kameranın birinci karakterin omzunu ve ensesini ön planda hafif flu bırakarak karşısındaki konuşmacıyı çerçevelediği ve karşı açısıyla kurgulandığı düzenek nedir?', 'Omuz üstü çekim (over-the-shoulder / OTS) ve açı-karşı açı kurgusu', ['Kuşbakışı tepe çekimi (bird\'s-eye view) ve metrik montaj kurgusu', 'Eğik Hollanda açısı (Dutch angle) ve sıçramalı eksilti kurgusu', 'Aşırı genel manzara çekimi (extreme long shot) ve zincirleme geçiş'], 'Omuz üstü çekimler açı-karşı açı (shot/reverse shot) kurgusunda iki karakter arasındaki fiziksel mesafeyi ve mekânsal bağı her planda canlı tutar.'),
  ('Bir sahnenin başından sonuna dek tüm oyuncuları ve diyalogları kapsayacak biçimde kesintisiz çekilen, kurgucuya yakın planlara girip çıkarken güvenli bir omurga sağlayan genel çekime ne ad verilir?', 'Ana çekim (master shot)', ['Kapanış jenerik çekimi (end-credit shot)', 'Yedek hava durumu çekimi (weather cover)', 'Hareketli takip çekimi (tracking shot)'], 'Master shot tüm sahneyi baştan sona kesintisiz kapsar; kurgucu yakın planlarda devamlılık sorunu yaşadığında her zaman ana çekime geri dönebilir.'),
  ('Sette her çekim sırasında oyuncuların hangi elleriyle sigara tuttuğunu, ceket düğmelerinin ilikli olup olmadığını, saç ayrımını ve bakış yönlerini titizlikle not alarak kurgucuya devamlılık raporu hazırlayan görevli kimdir?', 'Devamlılık yazmanı (script supervisor)', ['Birinci kamera asistanı (focus puller)', 'Işık şefi (gaffer)', 'Set amiri (key grip)'], 'Devamlılık yazmanı (sekreteri), aylar süren ve sırasız çekilen planların kurgu masasında kusursuz birleşebilmesi için tüm görsel ve metinsel tutarlılığı kayıt altına alır.'),
  ('Alfred Hitchcock\'un \'Sapık\' (Psycho, 1960) filmindeki ünlü duş sahnesinde bıçağın vücuda saplandığını doğrudan göstermediği halde izleyicide korkunç bir şiddet algısı yaratmasının kurgusal sırrı nedir?', 'Yaklaşık kırk beş saniyede yetmişten fazla çok kısa planı çığlık ve keman sesleriyle hızla çarpıştırması', ['Sahneyi hiç kesme yapmadan tek bir sabit röntgen kamerasıyla baştan sona kaydetmesi', 'Kan rengini parlak kırmızıya boyayıp ağır çekimde beş dakika boyunca ekranda tutması', 'Katilin yüzünü yakın planda net biçimde göstererek diyaloglarla cinayet nedenini açıklaması'], 'Hitchcock ve kurgucu George Tomasini hızlı metrik/ritmik kesmelerle şiddeti seyircinin kendi zihninde tamamlamasını sağlamıştır.'),
  ('Bir karakter koridordan sağa doğru yürüyüp kadrajdan çıktığında, bir sonraki odanın çekiminde kapıdan ne taraftan girmesi klasik ekran yönü sürekliliğine uygundur?', 'Kadrajın sol kenarından girip sağa doğru yürümeyi sürdürmesi', ['Kadrajın sağ kenarından girip gerisin geri sola doğru yürümesi', 'Kameranın tam arkasından dolaşıp tavandan aşağı doğru inmesi', 'Ekranın tam ortasında hareketsiz dururken birdenbire belirmesi'], 'Yön sürekliliği (directional continuity) gereği kadrajın sağından çıkan bir özne yeni planda soldan girdiğinde izleyici zihninde doğrusal bir ilerleme çizgisi korunur.'),
  ('Klasik kurguda bir şakadan, şok edici bir haberden veya gerilimli bir tehditten hemen sonra konuşan kişide kalmak yerine onu dinleyen karakterin sessiz yüz ifadesine kesilmesine ne ad verilir?', 'Tepki çekimi (reaction shot)', ['Kurucu genel çekim (establishing shot)', 'Omuz üstü takip çekimi (OTS tracking)', 'Nötr yön çekimi (neutral angle shot)'], 'Tepki çekimi özellikle komedi zamanlamasında ve dramatik gerilimde kilit rol oynar; seyirci olayın duygusal ağırlığını konuşandan çok dinleyenin yüzünden okur.'),
  ('Bir korku filminde karakterin karanlık koridordaki dolaba doğru yavaşça yürüdüğü çekimler ile karakterin kendi gözünden dolap kapağına yaklaşan öznel (POV) çekimlerin almaşık kurgulanması ne işe yarar?', 'İzleyiciyi karakterin savunmasız bakış açısıyla özdeşleştirerek bilinmeyene duyulan gerilimi artırır', ['Koridorun mimari planını emlak tanıtım videosu netliğinde tarafsızca sergiler', 'Dolabın içindeki canavarın geçmiş öyküsünü geriye dönüşlerle ayrıntılı açıklar', 'Sahnenin komedi tonuna geçmesini sağlayarak korku atmosferini tamamen dağıtır'], 'Karakterin bakan yüzü ile baktığı öznel (point-of-view) hareketli kameranın art arda kurgulanması, seyirciyi doğrudan tehlikenin gözlerine yerleştirir.'),
  ('Kurguda \'motive edilmiş kesme\' (motivated cut) ilkesine göre bir plandan diğerine geçmek için aşağıdakilerden hangisi geçerli bir tetikleyici sayılır?', 'Kadraj dışından gelen ani bir kapı çarpması sesi ve oyuncunun başını o yöne çevirmesi', ['Kurgucunun her yedi saniyede bir rastgele kesme yapma alışkanlığına sahip olması', 'Setteki kameramanın yorulup çekimi cümlenin tam ortasında yarıda bırakması', 'Laboratuvarda film makarasının kimyasal leke yüzünden ortadan kopması'], 'Görünmez kurguda her kesmenin izleyiciye mantıklı gelecek görsel ya da işitsel bir nedeni (motivasyonu) olmalıdır; bakış veya dış ses en güçlü kesme motivasyonlarıdır.'),
  ('Bir kurgucu yürüyerek sohbet eden iki karakterin sahnesinde genel çekimden yakın çekime keserken bir karakterin sağ ayağının önde olduğu kareyi ikinci çekimde sol ayağının önde olduğu kareye bağlarsa hangi hata oluşur?', 'Fiziksel hareket ve duruş devamlılığı hatası', ['Ses örnekleme frekansı uyumsuzluğu hatası', '180 derece bakış ekseni atlama hatası', 'Öykü dışı müzik telif ihlali hatası'], 'Özellikle boy veya diz planlarında yürüyüş adımlarının fazı eşleşmezse karakter kesme noktasında tökezlemiş ya da sekmiş gibi görünür.'),
  ('Sinema kurgusunda \'üçlü kesme\' veya \'bakış-nesne-tepki\' (point-of-view yapısı) dizilimi hangi sırayla işlediğinde en güçlü dramatik etkiyi üretir?', 'Önce bakan karakterin yüzü, ardından gördüğü şeyin çekimi, son olarak karakterin yüzündeki duygusal değişim', ['Önce beş saniyelik siyah ekran, ardından filmin son jeneriği, son olarak genel sokak manzarası', 'Önce konuşulan konunun yazılı özeti, ardından ses kayıt cihazı, son olarak mikrofon gölgesi', 'Önce hızlı bir kırbaç kaydırma, ardından dairesel silinme, son olarak ağır çekim yürüyüş'], 'Klasik öznel bakış (POV) üçlüsü, Kuleşov etkisini devamlılık kurgusuna uyarlayarak bakan özne, bakılan nesne ve doğan duyguyu kusursuz bir neden-sonuç halkasına bağlar.'),
  ('Bir kurgucu \'kapıdan kapıya\' (door-to-door) geçiş yaparken karakterin evinden çıkıp işyerindeki odasına kadar yürüdüğü yirmi dakikalık yolu göstermek yerine ev kapısından çıkışı doğrudan ofis kapısından girişe bağlıyorsa hangi temel ilkeyi kullanmaktadır?', 'Hareket sürekliliğini koruyarak öykü dışı gereksiz zamanı ayıklayan eliptik kesmeyi', ['Gerçek zaman ile ekran zamanını saniyesi saniyesine eşitleyen kesintisiz gözlemi', 'İki ayrı karakterin aynı anda uyanışını karşılaştıran almaşık kurguyu', 'Karakterin işyerini aslında hayal ettiğini belirten bulanık bindirmeyi'], 'Devamlılık kurgusu gerçek zamanı birebir kopyalamaz; hareket eşleşmesiyle kapıdan çıkışı diğer kapıdan girişe bağlayarak aradaki anlamsız yolculuk süresini görünmez biçimde atlar.'),
  ('Sette \'coverage\' (kapsama çekimleri) almak ifadesi kurgu masası açısından neyi güvence altına alır?', 'Aynı sahnenin genel, ikili, omuz üstü ve tekli yakın planlardan çekilerek kurgucuya zengin kesme seçenekleri sunulmasını', ['Çekim ekibinin yağmurlu havalara karşı kamera sigortası poliçesini eksiksiz imzalamasını', 'Filmin tüm yabancı ülkelerdeki televizyon yayın haklarının önceden satılmasını', 'Ses kayıt cihazının yedek pillerinin her saat başı düzenli olarak değiştirilmesini'], 'Yeterli \'coverage\' (farklı açı ve ölçek alternatifleri) çekilmemiş bir sahnede kurgucunun ritmi değiştirme, hataları gizleme ve performansı şekillendirme eli kolu bağlanır.'),
  ('Klasik devamlılık kurgusunda bir karakterin pencereden dışarı baktığı çekimin hemen ardından gelen dış mekân çekiminde kameranın pencerenin bulunduğu yükseklikten ve açıdan çekim yapması neyi pekiştirir?', 'Görüntünün karakterin kendi gözünden (öznel POV) görüldüğü yanılsamasını', ['Dışarıdaki sokağın karakterden bağımsız nesnel bir belgesel görüntüsü olduğunu', 'Sahnenin yirmi yıl öncesine ait bir çocukluk anısı olduğunu', 'Karakterin pencereden atlamak üzere olduğu fiziksel tehlikesini'], 'İkinci kattaki pencereden aşağı bakan birinin ardından zemin seviyesinden değil yukarıdan aşağı eğimli (high angle) sokak planına kesmek, bakış açısı devamlılığını doğrular.'),
  ('Bir kurgucu diyalog sahnesinde konuşmacının \'ııı\', \'şey\' gibi duraksamalarını temizlerken aynı açıdaki iki çekimi doğrudan birbirine bağlamak yerine hangi klasik devamlılık çözümüne başvurur?', 'Kesme yerinin üstünü konuşmacıyı dinleyen kişinin kısa bir tepki planıyla (B-roll veya reaction shot) örter', ['Kesilen yerin tam ortasına patlama sesi ve parlak beyaz flaş efekti yerleştirir', 'Görüntüyü ters çevirerek karakterin ekranın sağından soluna geçmesini sağlar', 'Konuşmanın geri kalan kısmını tamamen sessize alıp altyazıyla tamamlar'], 'L-cut ve J-cut yardımıyla ses alt katmanda temizlenirken üst görüntü katmanına dinleyici tepkisi veya detay plan koymak kesme izini tamamen görünmez kılar.'),
  ('Sinemada çekim başında ses ile görüntünün kurguda eşzamanlanmasını sağlamak için birbirine vurularak keskin bir ses çıkaran tahta veya plastik araca ne ad verilir?', 'Klaket', ['Steadicam', 'Vizör ve objektif kapağı', 'Işık ölçer pozometre'], 'Klaket hem üzerindeki sahne-plan-tekrar bilgilerini kameraya gösterir hem de kapanma anındaki keskin sesle senkron noktası oluşturur.'),
  ('Bir filmde karakterlerin de duyabildiği, hikâye evreninin içinden kaynaklanan kapı gıcırtısı, radyo sesi veya diyalog gibi sesler hangi kavramla adlandırılır?', 'Diegetik ses', ['Non-diegetik ses', 'Paralel kurgu müziği', 'Ses üstü anlatıcı kurgusu'], 'Diegetik (öyküsel) ses, kaynağını filmin kurmaca dünyasının içinden alan ve karakterlerce algılanabilen sestir.'),
  ('Yalnızca izleyicinin duyabildiği, filmdeki karakterlerin işitemediği gerilim müziği veya dış ses anlatımı hangi ses türüne girer?', 'Non-diegetik ses', ['Diegetik ortam sesi', 'Doğrudan set kaydı', 'Akustik oda tonu'], 'Non-diegetik (öykü dışı) ses, hikâye evreninin dışında yer alır ve dramatik etkiyi güçlendirmek için izleyiciye sunulur.'),
  ('Post-prodüksiyon aşamasında ayak sesi, kıyafet hışırtısı ve bardak şıkırtısı gibi gündelik ses efektlerini görüntüyle eşzamanlı olarak stüdyoda yeniden üreten sanatçıya ne denir?', 'Foley sanatçısı', ['Boom operatörü', 'Renk düzenleme uzmanı', 'Görüntü yönetmeni asistanı'], 'Adını ses öncüsü Jack Foley\'den alan Foley sanatçıları, fiziksel nesneler kullanarak görüntüye uyumlu doğal sesler üretir.'),
  ('Yabancı dildeki bir filmin özgün konuşmalarının silinerek yerine hedef dildeki seslendirme sanatçılarının kayıtlarının yerleştirilmesi işlemine ne ad verilir?', 'Dublaj', ['Altyazı gömme', 'Görüntü bindirme', 'Paralel kurgulama'], 'Dublaj, kaynak dildeki diyalog kanalının hedef dilde dudak hareketlerine uyumlu biçimde yeniden seslendirilmesidir.'),
  ('Sette kaydedilen kirli veya gürültülü oyuncu diyaloglarının post-prodüksiyon sürecinde ses stüdyosunda oyuncu tarafından yeniden seslendirilmesi hangi kısaltmayla bilinir?', 'ADR', ['CGI', 'VFX', 'FPS'], 'Automated Dialogue Replacement (ADR), teknik sorunlar nedeniyle sette temiz alınamayan konuşmaların stüdyoda yenilenmesidir.'),
  ('Film setinde mikrofonu oyuncuların başının üzerinde kadraja girmeden tutmak için kullanılan uzun uzatmalı çubuğa ne ad verilir?', 'Boom sopası', ['Dolly rayı', 'Jib kolu ve şaryo', 'Difüzör çerçevesi'], 'Boom sopası, yönlü mikrofonun ses kaynağına kadraj dışında kalarak en yakın mesafede tutulmasını sağlar.'),
  ('Açık hava çekimlerinde rüzgâr uğultusunun mikrofona çarpmasını önlemek için mikrofonun üzerine geçirilen tüylü kılıfa sinema jargonunda ne denir?', 'Deadcat', ['Barn door', 'Softbox örtüsü', 'Matte box filtresi'], 'Tüylü yapısıyla rüzgârın kinetik enerjisini dağıtan mikrofon koruyucusuna sektörde "deadcat" (rüzgâr tüyü) adı verilir.'),
  ('Bir film salonunda izleyicinin önünden, yanlarından ve arkasından farklı ses kanallarıyla çevrelenmesini sağlayan çok kanallı ses teknolojisi genel olarak nasıl adlandırılır?', 'Surround ses', ['Mono ses', 'Analog radyo yayını', 'Düzlemsel tek kanal'], 'Surround (çevresel) ses sistemleri, birden fazla hoparlör kanalı kullanarak izleyiciye üç boyutlu işitsel mekân hissi verir.'),
  ('Standart 5.1 çevresel ses sistemindeki ".1" rakamı hangi özel ses kanalını ifade eder?', 'Düşük frekanslı bas (LFE) kanalını', ['Merkez diyalog hoparlörünü', 'Tavan üstü tepe kanalını', 'Arka sağ çevre hoparlörünü'], '5.1 sisteminde beş ana tam aralıklı kanalın yanında ".1" ifadesi subwoofer üzerinden verilen LFE (Low-Frequency Effects) kanalını simgeler.'),
  ('5.1 sinema ses miksajında karakterlerin konuşmaları (diyaloglar) izleyicinin dikkatini perde üzerinde tutmak amacıyla ağırlıklı olarak hangi kanala yönlendirilir?', 'Merkez (Center) kanalına', ['Arka sol çevre kanalına', 'Yalnızca LFE bas kanalına', 'Sağ arka efekt kanalına'], 'Diyalogların perdenin tam arkasındaki merkez kanaldan gelmesi, salondaki her koltuktan sesin görüntüyle bütünleşik algılanmasını sağlar.'),
  ('Bir sahnenin görüntüsü henüz bitmeden bir sonraki sahnenin sesinin duyulmaya başlamasıyla kurulan işitsel geçiş tekniğine genel olarak ne ad verilir?', 'Ses köprüsü', ['Sıçramalı kesme', 'Kararma ve açılma', 'Göz hizası eşleşmesi'], 'Ses köprüsü (sound bridge), iki farklı sahneyi işitsel süreklilikle birbirine bağlayarak geçişi yumuşatan kurgu tekniğidir.'),
  ('Sinema tarihinde ilk uzun metrajlı senkronize diyaloglu ve şarkılı sesli film olarak kabul edilen 1927 yapımı eser hangisidir?', 'Caz Şarkıcısı (The Jazz Singer)', ['Bir Ulusun Doğuşu (The Birth of a Nation)', 'Ay\'a Seyahat (A Trip to the Moon)', 'Potemkin Zırhlısı (Battleship Potemkin)'], 'Alan Crosland\'ın yönettiği 1927 yapımı The Jazz Singer, Vitaphone ses sistemiyle senkronize konuşma içeren ilk uzun metrajlı filmdir.'),
  ('Film setinde tüm ekip sessizken mekânın kendi doğal uğultusunu yaklaşık otuz-altmış saniye boyunca kaydetmeye ne ad verilir?', 'Oda tonu', ['Foley miksajı', 'Ses üstü anlatım', 'Frekans modülasyonu'], 'Oda tonu, kurguda diyalog kesmeleri arasındaki boşlukları doldurarak sesin aniden kesilip yapaylaşmasını önler.'),
  ('Sinema ve televizyon yapımlarında çekilen ham görüntü ve ses planlarının seçilip anlamlı bir bütün oluşturacak şekilde ardışık olarak birleştirilmesi işlemine ne ad verilir?', 'Kurgu', ['Mizansen', 'Sinematografi', 'Koreografi'], 'Kurgu veya montaj, ayrı ayrı çekilmiş planların ritim, zaman ve anlam ilişkisi kuracak biçimde sıralanması sanatıdır.'),
  ('Bir ses kanalında aniden yükselen veya kesilen seslerin sert bir "çıt" sesi çıkarmasını önlemek için sesin kademeli olarak açılıp kısılmasına kurguda ne denir?', 'Fade in / Fade out (veya Crossfade)', ['Hard cut (Sert kesme)', 'Time stretching (Zaman esnetme)', 'Pitch shifting (Perde kaydırma)'], 'Ses kliplerinin başlangıç ve bitişlerine uygulanan yumuşak geçiş eğrileri (fade / crossfade), işitsel sıçramaları ve dijital tıklamaları engeller.'),
  ('Bir filmde geçen bir şarkının haklarının satın alınarak mevcut bir kaydın kullanılması yerine, filmin sahnelerine özel olarak bestelenen özgün enstrümantal müziğe ne ad verilir?', 'Film skoru', ['Ses efekti bankası', 'Diyalog kurgusu', 'Akustik kalibrasyon'], 'Original score, bestecinin filmin dramatik yapısına, temalarına ve kurgu ritmine özel olarak bestelediği özgün müzik bütünüdür.'),
  ('Darth Vader sahneye her çıktığında "Imperial March" (İmparatorluk Marşı) melodisinin duyulması gibi, belirli bir karakter, mekân veya fikirle özdeşleşen tekrar eden müzik temasına ne denir?', 'Leitmotiv (Ana motif)', ['Atonal doğaçlama', 'Beyaz gürültü (White noise)', 'Senkron klaket vuruşu'], 'Kökeni Richard Wagner operalarına dayanan leitmotiv, sinemada karakterleri veya dramatik kavramları simgeleyen yinelenen müzikal temadır.'),
  ('Bir sonraki sahnenin sesinin, bir önceki sahnenin görüntüsü henüz bitmeden birkaç saniye önce duyulmaya başladığı kurgu geçişine ne ad verilir?', 'J-cut', ['L-cut', 'Jump cut', 'Smash cut'], 'Zaman çizelgesinde (timeline) ses klibi görüntüden sola doğru uzanarak "J" harfine benzediği için bu ses köprüsü türüne J-cut denir.'),
  ('Bir sahnenin görüntüsü bittiği ve yeni sahnenin görüntüsüne geçildiği halde, önceki sahnenin sesinin bir süre daha devam ettiği kurgu tekniğine ne ad verilir?', 'L-cut', ['J-cut', 'Iris kapama geçişi', 'Kırbaç çevrinme'], 'Zaman çizelgesinde ilk sahnenin ses kanalı sağa doğru uzanıp "L" harfi şekli oluşturduğu için bu tekniğe L-cut (split edit) adı verilir.'),
  ('Aynı kamera açısıyla çekilmiş tek bir planın içinden zaman parçalarının çıkarılmasıyla öznenin kadrajda aniden yer değiştirmiş gibi göründüğü kesme türü hangisidir?', 'Sıçramalı kesme (Jump cut)', ['Görünmez kesme (Invisible cut)', 'Eylem eşleşmesi (Match on action)', 'Çapraz erime (Cross dissolve)'], 'Sıçramalı kesme (jump cut), kamera açısını yeterince değiştirmeden zamanı atlatarak süreklilik kurgusunu bilinçli veya hatalı biçimde kıran kesmedir.'),
  ('İfadesiz bir oyuncu yüzünün yanına sırasıyla bir tabak çorba, tabutta bir çocuk ve uzanmış bir kadın planı koyarak izleyicinin yüzdeki duyguyu her seferinde farklı yorumladığını kanıtlayan Sovyet sinemacı kimdir?', 'Lev Kuleşov', ['Andrey Tarkovski', 'Aleksandr Sokurov', 'Nikita Mihalkov'], 'Lev Kuleşov, Çarlık dönemi aktörü İvan Mozjuhin\'in aynı nötr yakın planını farklı görüntülerle birleştirerek anlamın tek plandan değil iki planın yan yana gelişinden doğduğunu göstermiştir.'),
  ('"Potemkin Zırhlısı" filmindeki ünlü Odessa Merdivenleri sahnesiyle tanınan ve çatışmaya dayalı "entellektüel montaj" kuramını geliştiren Sovyet yönetmen kimdir?', 'Sergey Ayzenştayn', ['Dziga Vertov', 'Vsevolod Pudovkin', 'Aleksandr Dovjenko'], 'Sergey Ayzenştayn, iki çekimin toplamından değil çarpışmasından üçüncü ve yeni bir kavramsal anlam doğduğunu savunarak Odessa Merdivenleri sekansını kurgulamıştır.'),
  ('Klasik Hollywood anlatısında izleyicinin kesmeleri fark etmeden kendisini tamamen hikâyenin akışına kaptırmasını amaçlayan kurgu anlayışına ne ad verilir?', 'Süreklilik kurgusu', ['Sovyet diyalektik montajı', 'Sıçramalı avangart kurgu', 'Rastlantısal kolaj montajı'], 'Süreklilik kurgusu (görünmez kurgu), mekân, zaman ve hareket tutarlılığını koruyarak kurgu müdahalesini izleyiciden gizlemeyi hedefler.'),
  ('Karşılıklı konuşan iki karakterin sahnesinde bakış yönlerinin tutarlı kalması için kameranın asla geçmemesi gereken hayali çizgi kuralı hangisidir?', '180 derece kuralı', ['Altın oran sarmalı', 'Üçler kuralı ızgarası', '30 derece açı kuralı'], 'İki karakter arasındaki hayali aks (eylem çizgisi) geçilirse karakterler kurguda aynı yöne bakıyormuş gibi görünür; bunu önleyen ilkeye 180 derece kuralı denir.'),
  ('Farklı mekânlarda aynı anda gerçekleşmekte olan iki veya daha fazla olayın dönüşümlü olarak kurgulanması tekniğine ne ad verilir?', 'Paralel kurgu (Cross-cutting)', ['Sıçramalı kesme (Jump cut)', 'Üst üste bindirme (Superimposition)', 'Dondurulmuş kare (Freeze frame)'], 'D.W. Griffith\'in son dakika kurtarma sahneleriyle popülerleştirdiği paralel kurgu (cross-cutting), eşzamanlı gelişen olaylar arasında gerilim ve bağ kurar.'),
  ('Bir görüntünün yavaşça kaybolurken bir sonraki görüntünün aynı anda yavaşça belirdiği ve genellikle zaman geçişini hissettiren kurgu geçişi hangisidir?', 'Zincirleme / Erime (Dissolve)', ['Keskin kesme (Hard cut)', 'Odak kaydırma (Rack focus)', 'Eğik kadraj (Dutch angle)'], 'Zincirleme (dissolve), iki planın kısa süreliğine şeffafça iç içe geçmesiyle sahneler arasında yumuşak bir zaman veya duygu bağlacı kurar.'),
  ('Bir karakterin kapıyı açmak için kolu indirmeye başladığı genel plandan, kapının açıldığı yakın plana tam hareketin ortasında kesme yapılmasına ne denir?', 'Hareket eşleşmesi (Match on action)', ['Sıçramalı kesme (Jump cut)', 'Entellektüel çarpışma', 'Geriye dönüş (Flashback)'], 'Hareketin bir planda başlayıp kesintisiz biçimde diğer planda tamamlanması (match on action), izleyicinin gözünü harekete odaklayarak kesmeyi görünmez kılar.'),
  ('1960 yapımı "Serseri Aşıklar" (À bout de souffle) filminde sıçramalı kesmeleri (jump cut) bilinçli bir üslup öğesi olarak kullanarak modern sinemada çığır açan Fransız Yeni Dalga yönetmeni kimdir?', 'Jean-Luc Godard', ['François Truffaut', 'Éric Rohmer', 'Claude Chabrol'], 'Jean-Luc Godard, araba yolculuğu sahnelerinde klasik kurgu kurallarını yıkan sıçramalı kesmeler kullanarak Yeni Dalga estetiğinin simgesini yaratmıştır.'),
  ('Bir sahnenin sonunda görüntünün kademeli olarak tamamen siyaha gömülmesi (fade to black) kurgu dilinde genellikle neyi ifade eder?', 'Önemli bir bölümün kapandığını veya belirgin bir zaman diliminin geçtiğini', ['Kamera pilinin çekim esnasında aniden tükendiğini', 'Aynı konuşmanın hiç ara verilmeden milisaniyesiyle sürdüğünü', 'Karakterin aynı odada başını hafifçe sağa çevirdiğini'], 'Siyaha kararma (fade out), sinemasal noktalama işaretlerinde bir bölüm sonu (nokta veya yeni paragraf) işlevi görerek dramatik duraklama yaratır.'),
  ('Uzun bir zaman dilimine yayılan antrenman, hazırlık veya büyüme sürecini müzik eşliğinde kısa ve hızlı planlarla özetleyen sekans türüne ne ad verilir?', 'Montaj sekansı (Montage sequence)', ['Tek plan sekans (Long take)', 'Klaket senkron planı', 'Açılış jeneriği yazısı'], '"Rocky" filmindeki antrenman sahnesi gibi uzun süreçleri ritmik kesmelerle birkaç dakikaya sıkıştıran anlatım birimine montaj sekansı denir.'),
  ('Bir karakterin kadraj dışındaki bir nesneye baktığı plandan sonra hemen o nesnenin gösterildiği plana kesme yapılması hangi süreklilik tekniğidir?', 'Bakış açısı / Göz hizası eşleşmesi (Eyeline match)', ['Ses köprüsü (Sound bridge)', 'Zaman atlamalı çekim (Time-lapse)', 'Kontrapuntal ses montajı'], 'Kuleşov etkisinden de beslenen göz hizası eşleşmesi (eyeline match), karakterin bakış yönüyle gördüğü nesne arasında mekânsal mantık kurar.'),
  ('Selüloit film şeritlerinin makas veya giyotinle fiziksel olarak kesilip bant ya da sementle yapıştırıldığı geleneksel kurgu yöntemine dijital kurgudan ayırmak için ne denir?', 'Doğrusal (Linear / Fiziksel) kurgu', ['Doğrusal olmayan (Non-linear) kurgu', 'Bulut tabanlı sanal kurgu', 'Algoritmik otomatik kurgu'], 'Dijital NLE (Non-Linear Editing) sistemlerinden önce selüloit şeritlerin fiziksel kesilip yapıştırılmasına veya video kasetten kasete sırayla aktarılmasına doğrusal/fiziksel kurgu denir.'),
  ('Bir sahnenin başında mekanın neresi olduğunu ve karakterlerin birbirine göre konumunu izleyiciye genel hatlarıyla tanıtan geniş açılı plana kurguda ne ad verilir?', 'Kurucu plan / Tanıtım planı (Establishing shot)', ['Aşırı yakın detay plan (Extreme close-up)', 'Omuz üstü tepki planı (Reaction shot)', 'Eğik Hollanda açısı (Dutch tilt)'], 'Kurucu plan (establishing shot), genellikle sahnenin başında yer alarak izleyicinin coğrafi ve mekânsal yönelimini kurar.'),
  ('İki kişinin karşılıklı konuşmasında kameranın bir karakterin omzunun hemen arkasından diğer karakterin yüzünü görecek şekilde konumlandırıldığı ve kurguda açı-karşı açı (shot-reverse shot) yapısını kuran çekim hangisidir?', 'Omuz üstü çekim (Over-the-shoulder / OTS)', ['Kuşbakışı tepe çekim (Bird\'s-eye view)', 'Solucan bakışı alt açı (Worm\'s-eye view)', 'Aşırı uzak manzara planı (Extreme long shot)'], 'Omuz üstü planlar (OTS), diyalog kurgusunda açı-karşı açı (shot-reverse shot) geçişleriyle karakterler arasındaki mekânsal mesafeyi ve ilişkiyi korur.'),
  ('Bir aksiyonun veya dramatik bir final anının tek bir fotoğraf karesi gibi ekranda hareketsiz bırakılmasına (örneğin Truffaut\'nun "400 Darbe" filminin son karesine) ne ad verilir?', 'Dondurulmuş kare (Freeze frame)', ['Hızlandırılmış çekim (Fast motion)', 'Bölünmüş ekran (Split screen)', 'Çapraz ses geçişi (Audio crossfade)'], 'François Truffaut\'nun "400 Darbe" (Les Quatre Cents Coups, 1959) finalinde Antoine Doinel\'in yüzünü dondurmasıyla ikonikleşen bu teknik "freeze frame" olarak adlandırılır.'),
  ('Telefonla konuşan iki farklı yerdeki karakteri aynı anda perdenin sağ ve sol yarısında birlikte gösteren kurgu ve kompozisyon tekniği hangisidir?', 'Bölünmüş ekran (Split screen)', ['Sıçramalı kesme (Jump cut)', 'Kararma geçişi (Fade to black)', 'Kuyruk klaketi (Tail slate)'], 'Split screen (bölünmüş ekran), kesme yapmaya gerek kalmadan farklı mekânlardaki eşzamanlı eylemleri tek çerçevede yan yana sunar.'),
  ('Kurgu sürecinde yönetmen ve kurgucunun tüm sahne sıralamasını ve kesme noktalarını kesinleştirip artık görüntü süresinde hiçbir değişiklik yapılmayacağını ilan ettikleri aşamaya ne denir?', 'Resim kilidi / Kurgu kilidi (Picture lock)', ['Kaba kurgu (Rough cut)', 'İlk dizilim (Assembly cut)', 'Sette günlük izleme (Dailies)'], 'Picture lock aşamasına gelindiğinde görüntü kurgusu dondurulur; böylece ses tasarımı, ADR, Foley ve müzik besteleme ekipleri kare kayması korkusu olmadan kesin senkronla çalışabilir.'),
  ('Sinemada çekimler arasındaki geçişlerin izleyici tarafından fark edilmeyecek kadar akıcı olmasını hedefleyen klasik kurgu anlayışına ne ad verilir?', 'Devamlılık kurgusu', ['Sovyet entelektüel montaj kuramı', 'Sıçramalı yabancılaştırma kurgusu', 'Diyalektik çarpışma montajı'], 'Klasik anlatı sinemasında zaman ve mekân bütünlüğünü koruyarak kesmeleri görünmez kılan sistem devamlılık kurgusudur.'),
  ('Bir karakterin kapıyı açmaya başladığı genel plandan, kapı kolunu çevirdiği yakın plana geçerken kesmenin tam hareket anında yapılması hangi kurgu tekniğidir?', 'Harekette kesme', ['Bakış yönü eşleşmesi', 'Paralel çapraz kurgu', 'Zamansal eksilti tekniği'], 'Fiziksel bir eylemin iki farklı ölçekteki plan arasında kesintisiz akmasını sağlayan tekniğe harekette kesme (match on action) denir.'),
  ('Birinci planda kadraj dışındaki bir noktaya bakan karakterin ardından, ikinci planda baktığı nesnenin gösterilmesine dayanan kurgu kuralı hangisidir?', 'Bakış eşleşmesi', ['Grafiksel biçim eşleşmesi', 'Sessel köprüleme tekniği', 'Mekânsal eksen atlaması'], 'Karakterin bakış yönü ile gördüğü nesneyi ardışık iki planda birleştiren devamlılık ilkesi bakış eşleşmesidir (eyeline match).'),
  ('Farklı mekânlarda aynı anda gerçekleşen iki ayrı olay dizisinin sırayla birbirine kesilerek anlatılmasına ne ad verilir?', 'Paralel kurgu', ['Geriye dönüş kurgusu', 'Plan-sekans çekimi', 'Kaba kurgu dizilimi'], 'İki veya daha fazla eşzamanlı olayı nöbetleşe göstererek gerilimi ve anlatı bağını güçlendiren yöntem paralel kurgudur (cross-cutting).'),
  ('Hikâye süresini kısaltmak amacıyla anlatı açısından önemsiz zaman dilimlerinin kurguda atlanmasına ne ad verilir?', 'Eksilti', ['Uzatma', 'Dondurma', 'Bindirme'], 'Öykü zamanındaki gereksiz boşlukların çıkarılarak olayların daha kısa bir ekran süresinde sunulması eksilti (ellipsis) olarak adlandırılır.'),
  ('Bir sahnenin hiçbir kurgu kesmesi yapılmaksızın tek bir kesintisiz çekimle baştan sona kaydedilmesine ne ad verilir?', 'Plan-sekans', ['Omuz planı', 'Eğik kadraj', 'Kurgusal sekans'], 'Sahnenin bütün dramatik akışını kesme kullanmadan tek bir uzun plan içinde sunan çekim tekniği plan-sekanstır.'),
  ('Çekilen ham görüntülerin senaryo sırasına göre ilk kez bir araya getirildiği, ritim ve ince zamanlama ayarlarının henüz yapılmadığı kurgu aşaması hangisidir?', 'Kaba kurgu', ['Son kurgu', 'Renk düzeltme', 'Ses miksajı'], 'Yönetmen ve kurgucunun sahnelerin genel yapısını görmek için oluşturduğu ilk geniş montaj taslağına kaba kurgu (rough cut) denir.'),
  ('Görüntü kurgusunun tamamen kilitlendiği, hiçbir planın süresinin veya yerinin artık değiştirilmediği nihai kurgu aşamasına ne ad verilir?', 'Son kurgu', ['Ön kurgu', 'Ham dizilim', 'Vekil kurgu'], 'Ses tasarımı, görsel efekt ve renk aşamalarına geçilmeden önce onaylanan kesinleşmiş kurgu versiyonu son kurgudur (final cut / picture lock).'),
  ('Karşılıklı konuşan iki karakterin ekranda hep tutarlı yönlere bakmasını sağlamak için kameraların aşmaması gereken hayalî çizgi hangisidir?', '180 derece çizgisi', ['Altın oran çizgisi', 'Ufuk düzlemi ekseni', 'Üçler kuralı ızgarası'], 'İki oyuncu arasındaki aks çizgisinin aynı tarafında kalınmasını şart koşan temel devamlılık ilkesi 180 derece kuralıdır.'),
  ('Ardışık iki plan arasında kamera açısının en az ne kadar değiştirilmesi gerektiğini belirten ve sıçrama hissini önleyen kural hangisidir?', '30 derece kuralı', ['90 derece kuralı', '45 derece kuralı', '120 derece kuralı'], 'Aynı özneye yapılan ardışık kesmelerde görüntünün takılmış gibi sıçramaması için kamera açısı en az 30 derece değiştirilmelidir.'),
  ('Aynı sahne içinde öznenin konumu çok az değişirken kamera açısının neredeyse aynı kalması sonucu oluşan sarsıcı ve kopuk geçişe ne ad verilir?', 'Sıçramalı kesme', ['Görünmez kesme', 'Yumuşak geçiş', 'Eşleşmeli kesme'], 'Zaman atlamasını belli eden ve klasik devamlılığı bilerek ya da hata sonucu kıran kesme türü sıçramalı kesmedir (jump cut).'),
  ('Post-prodüksiyon sürecinde farklı kameralarla veya ışık koşullarıyla çekilmiş planların parlaklık ve beyaz dengesini eşitleme işlemine ne denir?', 'Renk düzeltme', ['Renk derecelendirme', 'Görsel birleştirme', 'Görüntü keskinleştirme'], 'Görüntüleri doğal ve birbiriyle tutarlı bir temel seviyeye getiren teknik işleme renk düzeltme (color correction) adı verilir.'),
  ('Bir sahnenin dramatik atmosferini güçlendirmek için görüntülere soğuk mavi veya sıcak kehribar gibi sanatsal bir renk tonu kazandırma işlemi hangisidir?', 'Renk derecelendirme', ['Beyaz dengesi kalibrasyonu', 'Pozlama telafisi ayarı', 'Gürültü azaltma işlemi'], 'Teknik düzeltmenin ardından filme estetik ve duygusal bir görsel kimlik verme aşaması renk derecelendirmedir (color grading).'),
  ('Yüksek çözünürlüklü ham kamera dosyaları yerine bilgisayarın daha hızlı işlemesi için oluşturulan düşük boyutlu kopya dosyalara ne ad verilir?', 'Proxy dosyası', ['Master kopya', 'Ham negatif', 'Renk tablosu'], 'Kurgu yazılımında takılmadan çalışabilmek için orijinal medyadan üretilen hafif çalışma kopyalarına proxy (vekil) dosyası denir.'),
  ('Sette ses ve görüntünün kurgu aşamasında kolayca eşleştirilebilmesi için çekim başında kameraya gösterilip kapatılan araç nedir?', 'Klake', ['Reflektör', 'Vizör', 'Gimbal'], 'Üzerinde sahne, plan ve tekrar numaraları yazan, çıkardığı keskin sesle senkronizasyon sağlayan araç klakedir (slate/clapperboard).'),
  ('Bir sonraki sahnenin sesinin, mevcut sahnenin görüntüsü henüz bitmeden duyulmaya başladığı kurgu geçişine ne ad verilir?', 'J kesme', ['L kesme', 'Sert kesme', 'Zincirleme geçiş'], 'Zaman çizelgesinde ses kanalının görüntüden önce girmesiyle J harfine benzer bir biçim oluşturan geçiş J kesmedir (J-cut).'),
  ('Mevcut sahnenin görüntüsü bittiği ve yeni sahnenin görüntüsüne geçildiği hâlde, önceki sahnenin sesinin bir süre daha devam etmesine ne denir?', 'L kesme', ['J kesme', 'Sıçramalı kesme', 'Kararma geçişi'], 'Görüntü kesildikten sonra sesin alttan akmayı sürdürdüğü ve diyalog sahnelerinde doğallık sağlayan geçiş L kesmedir (L-cut).'),
  ('Bir görüntünün yavaşça kaybolurken bir sonraki görüntünün onun üzerinde yavaşça belirdiği ve genellikle zaman geçişini simgeleyen etki hangisidir?', 'Zincirleme', ['Sert kesme', 'Odak kaydırma', 'Keskin silinme'], 'İki planın üst üste binerek yumuşak biçimde birbirine dönüştüğü kurgu geçişine zincirleme (dissolve) denir.'),
  ('Bir sahnenin sonunda görüntünün kademeli olarak tamamen siyaha gömülmesiyle oluşturulan geçiş tekniğine ne ad verilir?', 'Kararma', ['Açılma', 'Bindirme', 'Aydınlanma'], 'Genellikle bir bölümün veya dramatik bir zaman diliminin kapandığını belirten siyaha geçiş tekniği kararmadır (fade out).'),
  ('Görüntü kurgusu tamamlandıktan sonra tüm diyalog, müzik ve ses efektlerinin ses seviyelerinin dengelenip harmanlandığı aşama hangisidir?', 'Ses miksajı', ['Kaba montaj', 'Renk ayrımı', 'Kurgu kilidi'], 'Farklı ses kanallarının temizlenip estetik ve işitsel standartlara göre birleştirildiği son ses aşaması ses miksajıdır (sound mixing).'),
  ('Diyalog sahnelerinde oyuncuların konuşmalarını ve tepkilerini sırayla karşıdan karşıya gösteren klasik çekim ve kurgu düzenine ne ad verilir?', 'Açı-karşı açı', ['Kuşbakışı genel plan', 'Eğik eksenli plan', 'Kesintisiz takip planı'], 'İki karakter arasındaki konuşmayı karşılıklı omuz üstü veya tekli planlarla kurgulayan standart yöntem açı-karşı açıdır (shot/reverse shot).'),
  ('Kameranın sensöründen gelen veriyi sıkıştırmadan veya çok az işleyerek maksimum renk ve dinamik aralık bilgisiyle saklayan kayıt formatı hangisidir?', 'RAW formatı', ['MP4 formatı', 'JPEG dizisi', 'GIF formatı'], 'Post-prodüksiyonda renk ve pozlama müdahalesine en geniş esnekliği tanıyan işlenmemiş veri kaydı RAW formatıdır.'),
  ('Bir mekânın dıştan genel görünüşünü vererek izleyicinin sahnenin nerede geçtiğini anlamasını sağlayan açılış planına ne ad verilir?', 'Tanıtıcı plan', ['Detay planı', 'Tepki planı', 'Ara kesme planı'], 'Yeni bir sahnenin coğrafyasını ve karakterlerin mekânsal ilişkisini kuran geniş ölçekli çekime tanıtıcı plan (establishing shot) denir.'),
  ('Çekim gününün sonunda görüntü ve seslerin senkronize edilerek yönetmen, görüntü yönetmeni ve yapımcının izlemesi için hazırlanan günlük ham çekim kopyalarına ne ad verilir?', 'Dailies', ['Fragman kurgusu', 'Dağıtım paketi', 'Görsel efekt katmanı'], 'Setteki çekimlerin teknik ve sanatsal açıdan sorunsuz kaydedilip kaydedilmediğini denetlemek için her gün hazırlanan izleme kopyalarına dailies (veya rushes) denir.'),
  ('Bilgisayar üzerinde görüntü ve ses dosyalarına zarar vermeden istenildiği sırayla kurgu yapılmasını sağlayan modern dijital kurgu sistemlerine genel olarak ne ad verilir?', 'Doğrusal olmayan kurgu', ['Doğrusal kaset kurgusu', 'Optik film banyosu', 'Mekanik şerit kesimi'], 'Sahnelerin baştan sona sırayla kaydedilme zorunluluğunu kaldıran ve istenen an araya plan eklemeye izin veren yazılımlara Non-Linear Editing (NLE) denir.'),
  ('Bir görüntü karesinin aniden durdurularak fotoğraf gibi sabit bırakılmasıyla dramatik vurgu yaratan kurgu efektine ne ad verilir?', 'Donuk kare (Freeze frame)', ['Ağır çekim (Slow motion)', 'Hızlı kaydırma (Whip pan)', 'Yumuşak kararma (Fade out)'], 'François Truffaut\'nun 400 Darbe filminin finalinde olduğu gibi akışı bir anda dondurarak hafızaya kazıyan tekniğe freeze frame denir.'),
  ('Ekranın aynı anda iki veya daha fazla bölmeye ayrılarak farklı mekânlardaki karakterlerin (örneğin telefonla konuşan iki kişinin) birlikte gösterildiği teknik nedir?', 'Bölünmüş ekran', ['Açı-karşı açı kurgusu', 'Karanlığa zincirleme geçiş', 'Tekli omuz üstü plan'], 'Farklı görüntüleri aynı kadraj içinde yan yana veya üst üste sunan kompozisyon ve kurgu tekniği bölünmüş ekrandır.'),
  ('Sette çekim devam ederken kıyafet, saç, makyaj, aksesuar ve bakış yönü gibi ayrıntıların planlar arasında bozulmamasını not tutarak takip eden görevli kimdir?', 'Devamlılık yazmanı (Script supervisor)', ['Set ışık şefi (Gaffer)', 'Foley ses sanatçısı', 'Renk derecelendirme uzmanı'], 'Kurguda devamlılık hataları yaşanmaması için her çekimin ayrıntılı raporunu tutan set çalışanı devamlılık asistanı / script supervisor\'dır.'),
  ('Görüntünün ekranın bir kenarından diğerine doğru geometrik bir çizgi veya şekil hâlinde silinerek yerini yeni sahneye bıraktığı klasik geçiş hangisidir?', 'Silinme (Wipe)', ['Sert kesme (Cut)', 'Sıçrama (Jump cut)', 'Odaklanma (Rack focus)'], 'Özellikle Yıldız Savaşları (Star Wars) serisiyle özdeşleşen, yeni görüntünün öncekini iterek ekranı kapladığı geçiş türü silinmedir (wipe).'),
  ('Tamamen siyah bir ekranın kademeli olarak aydınlanıp sahnenin ilk görüntüsünü ortaya çıkarmasıyla başlayan geçişe ne ad verilir?', 'Açılma (Fade in)', ['Kararma (Fade out)', 'Harekette kesme', 'Paralel kurgu'], 'Filmin veya yeni bir dramatik perdenin başlangıcını imleyen, siyahtan görüntüye geçiş tekniği açılmadır (fade in).'),
  ('Kurgu yazılımlarında tüm görüntü ve ses kanallarının yatay zaman ekseni boyunca dizildiği çalışma alanına ne ad verilir?', 'Zaman çizelgesi (Timeline)', ['Medya havuzu (Bin)', 'Renk tekerleği (Color wheel)', 'Vektörskop ekranı'], 'Kurgucunun planları sıraladığı, kestiği ve ses katmanlarını üst üste yerleştirdiği temel çalışma paneli zaman çizelgesidir.'),
  ('Her bir görüntü karesini saat, dakika, saniye ve kare numarası (SS:DD:SN:KR) biçiminde benzersiz olarak etiketleyen sayısal sisteme ne ad verilir?', 'Zaman kodu', ['Enstantane hızı', 'Diyafram değeri', 'Renk sıcaklığı'], 'Post-prodüksiyon boyunca görüntü, ses ve görsel efektlerin hatasız eşleştirilmesini sağlayan adresleme sistemi zaman kodudur.'),
  ('Bir karakterin omuz hizasından ve ensesinin hemen arkasından çekilerek karşısındaki konuşmacıyı çerçeveleyen, mekânsal ilişkiyi koruyan plan ölçeği hangisidir?', 'Omuz üstü plan', ['Kuşbakışı genel plan', 'Aşırı detay planı', 'Öznel bakış planı'], 'Diyalog kurgusunda iki karakterin birbirine olan mesafesini ve 180 derece eksenini izleyiciye sürekli hatırlatan çekim omuz üstü plandır.'),
  ('Kameranın tam olarak karakterin gözlerinin bulunduğu yere yerleştirilerek izleyicinin dünyayı doğrudan karakterin gözünden gördüğü çekime ne denir?', 'Öznel bakış planı', ['Tanıtıcı dış plan', 'Üçlü grup planı', 'Eğik Hollanda açısı'], 'Bakış eşleşmesinde karakterin baktığı şeyi doğrudan onun görüş açısından sunan çekim Point of View (POV - öznel plan) olarak adlandırılır.'),
  ('Hikâyenin şimdiki zaman akışı kesilerek karakterin geçmişte yaşadığı bir olayın araya girmesiyle oluşturulan zamansal kurgu tekniği nedir?', 'Geriye dönüş (Flashback)', ['İleriye atlama (Flashforward)', 'Eşzamanlı paralel kurgu', 'Kesintisiz plan-sekans'], 'Anlatının kronolojik sırasını kırarak geçmişteki bir nedeni veya travmayı gösteren kurgusal geçiş geriye dönüştür.'),
  ('Öykünün mevcut zamanından koparak gelecekte yaşanacak bir olayı anlık veya sahne bütünlüğünde izleyiciye gösterip tekrar şimdiye dönen teknik nedir?', 'İleriye atlama (Flashforward)', ['Geriye dönüş (Flashback)', 'Harekette eşleşme', 'Oda sesi döşeme'], 'Gelecekteki bir sonucu şimdiden göstererek merak ve dramatik ironi yaratan zamansal kurgu hamlesi ileriye atlamadır.'),
  ('Setten gelen kamera hafıza kartlarının güvenli biçimde yedeklenmesinden, doğrulanmasından ve proxy dosyalarının hazırlanmasından sorumlu teknik uzman kimdir?', 'DIT', ['ADR yönetmeni', 'Sanat yönetmeni', 'Koreografi uzmanı'], 'Kamera verisinin kayıpsız aktarımı (checksum), renk ön-izleme LUT\'ları ve post-prodüksiyon köprüsünü kuran görevli Digital Imaging Technician\'dır.'),
  ('Filmin başında veya sonunda yer alan oyuncu, yönetmen ve teknik ekip isimlerinin aktığı yazı düzenlemelerine ne ad verilir?', 'Jenerik (Credits)', ['Altyazı (Subtitles)', 'Zaman kodu (Timecode)', 'Klake (Slate)'], 'Yapımda emeği geçen kişi ve kurumların belirli bir grafik tasarımla sunulduğu açılış ve kapanış yazıları jeneriktir.'),
  ('Orijinal müzik bestesi henüz tamamlanmamışken kurgucunun sahnenin duygusunu ve ritmini bulmak için kaba kurguya geçici olarak yerleştirdiği hazır müziğe ne denir?', 'Geçici müzik (Temp track)', ['Oda sesi (Room tone)', 'Foley efekti', 'Zaman kodu sinyali'], 'Yönetmen ve besteciye sahnenin hedeflediği ton hakkında fikir veren, son miksajda çıkarılan rehber müzik geçici müziktir.'),
  ('Bir görüntünün en karanlık gölge alanları ile en parlak ışık alanları arasındaki ton farkı oranına ne ad verilir?', 'Kontrast', ['Doygunluk', 'Netlik', 'Kare hızı'], 'Renk düzeltmenin en temel adımlarından biri olan siyah-beyaz ton açıklığı ve derinlik ilişkisi kontrasttır.'),
  ('Kameradaki beyaz bir nesnenin ortam ışığının renginden (sarı ampul veya mavi gölge) etkilenmeden kurguda gerçek beyaz olarak görünmesini sağlayan ayar nedir?', 'Beyaz dengesi', ['Alan derinliği ayarı', 'Ses seviyesi eşitlemesi', 'En-boy oranı kesimi'], 'Görüntüdeki istenmeyen renk sapmalarını (color cast) gidererek doğal renkleri yakalamanın ilk koşulu doğru beyaz dengesidir.'),
  ('Görüntünün genişliğinin yüksekliğine olan matematiksel oranını (örneğin 16:9, 2.39:1 veya 4:3) ifade eden sinema terimi hangisidir?', 'En-boy oranı', ['Çözünürlük değeri', 'Bit derinliği', 'Örnekleme hızı'], 'Çerçevenin yatay ve dikey formunu belirleyen, kurgu proje ayarlarının temelini oluşturan ölçü en-boy oranıdır.'),
  ('Canlı televizyon yayınlarında (maç, konser, haber) birden fazla kameradan gelen görüntüleri anlık olarak seçip yayına veren kurgu masası ve görevlisine ne denir?', 'Reji masası ve yönetmen / resim seçici', ['Renk odası ve renk uzmanı', 'Foley stüdyosu ve sesçi', 'DIT istasyonu ve veri uzmanı'], 'Çok kameralı canlı yayınlarda gerçek zamanlı kurgu kararlarının uygulandığı merkez reji, geçişleri yapan operatör ise resim seçicidir (vision mixer).'),
  ('Belgesel veya haber kurgusunda röportaj veren kişinin konuşması alttan devam ederken, anlattığı konuyla ilgili gösterilen destekleyici görüntülere ne ad verilir?', 'B-Roll (Destek görüntüleri)', ['A-Roll (Ana röportaj)', 'Klake çekimi', 'Renk barı'], 'Konuşan kafa (A-Roll) görüntüsünün tekdüzeliğini kıran, kesmeleri gizleyen ve anlatılanı görselleştiren ek çekimlere B-Roll denir.'),
  ('Filmin yabancı ülkelerde dublaj yapılabilmesi için diyalog kanalı çıkarılmış, yalnızca müzik ve ses efektlerini barındıran özel ses teslimat dosyasına ne denir?', 'M&E kanalı', ['ADR ham kaydı', 'Kaba kurgu sesi', 'Mono rehber kanal'], 'Uluslararası dağıtım iş akışında her ülkenin kendi dilindeki dublajı üzerine ekleyebilmesi için zorunlu tutulan miksaj paketi M&E kanalıdır.'),
];
